// Decompile every function and write one C file plus a function index CSV.
// Script args: <out.c> [index.csv]
//@category RT950
import java.io.PrintWriter;

import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileOptions;
import ghidra.app.decompiler.DecompileResults;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.Function;

public class ExportDecompiled extends GhidraScript {

	@Override
	public void run() throws Exception {
		String[] args = getScriptArgs();
		if (args.length < 1) {
			throw new IllegalArgumentException("usage: ExportDecompiled.java <out.c> [index.csv]");
		}
		DecompInterface ifc = new DecompInterface();
		ifc.setOptions(new DecompileOptions());
		ifc.toggleCCode(true);
		ifc.toggleSyntaxTree(false);
		if (!ifc.openProgram(currentProgram)) {
			throw new IllegalStateException("Decompiler: " + ifc.getLastMessage());
		}
		int ok = 0, failed = 0, bad = 0;
		PrintWriter idx = args.length > 1 ? new PrintWriter(args[1], "UTF-8") : null;
		if (idx != null) {
			idx.println("address,name,size,decompiled");
		}
		try (PrintWriter w = new PrintWriter(args[0], "UTF-8")) {
			w.println("// Decompiled from " + currentProgram.getName() + " by Ghidra "
				+ ghidra.framework.Application.getApplicationVersion());
			w.println("// Generated by ghidra/analyze.sh, do not edit by hand.\n");
			for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
				monitor.checkCancelled();
				if (f.isThunk() || f.isExternal()) {
					continue;
				}
				DecompileResults r = ifc.decompileFunction(f, 120, monitor);
				boolean good = r != null && r.decompileCompleted() && r.getDecompiledFunction() != null;
				w.println("// " + f.getEntryPoint() + " " + f.getName());
				if (good) {
					String c = r.getDecompiledFunction().getC();
					if (c.contains("halt_baddata")) {
						bad++;
					}
					w.println(c);
					ok++;
				}
				else {
					w.println("// decompilation failed: " + (r == null ? "?" : r.getErrorMessage()) + "\n");
					failed++;
				}
				if (idx != null) {
					idx.println(String.format("0x%08x,%s,%d,%s", f.getEntryPoint().getOffset(),
						f.getName(), f.getBody().getNumAddresses(), good));
				}
			}
		}
		finally {
			if (idx != null) {
				idx.close();
			}
			ifc.dispose();
		}
		println("Decompiled " + ok + " functions (" + bad + " with bad instruction data), " + failed + " failed");
	}
}
